  var installEscape = document.getElementById('staxx-install-note-escape');
  // PLAN_63 Phase D: the id of a caught install waiting to be stamped as an
  // Unraid template once its stack is saved — see the handoff hook at the end
  // of this file. Cleared the instant it has done its one job, and also by
  // openEditor() itself (below), so it can never attach itself to a stack it
  // had nothing to do with.
  var pendingHandoffId = '';
  // PLAN_63 Phase E item 19: whether the caught install now open is a
  // converted edit — the one caught-install kind with a real Unraid
  // container still running the old way behind it, so a save worth offering
  // the handover for. Lives and dies alongside pendingHandoffId above.
  var pendingHandoffEdit = false;
  // PLAN_106 phase 5 gap: the template's own, unescaped wording for a caught
  // install, so the first save of the new stack can file it into history
  // before the escaped text overwrites it — the CA import panel already gets
  // this for free through the write it makes itself; the single-app editor
  // route has no such write to piggyback on, so it sends this once instead.
  // Lives and dies alongside pendingHandoffId above, same reasoning.
  var pendingBodyAsIs = '';
  var pageNotice   = document.getElementById('staxx-page-notice');
  var pageNoticeIcon   = pageNotice ? pageNotice.querySelector('.fa') : null;
  var pageNoticeAction = document.getElementById('staxx-page-notice-action');
  var refNote      = document.getElementById('staxx-refnote');
  var gapNote     = document.getElementById('staxx-required-note');
  // PLAN_65 phase C — the "what clashed" summary. No server-rendered element
  // exists for this (the plan scopes the work to this file alone), so it is
  // built once here, as a sibling of gapNote, reusing #staxx-inusepaths' own
  // caution styling rather than inventing a fourth one.
  var clashNote = document.createElement('p');
  clashNote.className = 'staxx-missing staxx-missing--inuse';
  clashNote.id = 'staxx-clash-note';
  clashNote.hidden = true;
  if (gapNote && gapNote.parentNode) gapNote.parentNode.insertBefore(clashNote, gapNote);
  // PLAN_62 Stage 3 — what the author's published example adds or drops that
  // has no field of its own to sit on (mostly additions — the local file has
  // no line to attach one to), plus why a comparison could not even be
  // attempted. Built here for the same reason clashNote is: this plan also
  // scopes the work to this file alone.
  var watchNote = document.createElement('p');
  watchNote.className = 'staxx-missing staxx-missing--inuse';
  watchNote.id = 'staxx-watch-note';
  watchNote.hidden = true;
  if (gapNote && gapNote.parentNode) gapNote.parentNode.insertBefore(watchNote, gapNote);
  // PLAN_70 stage 2 — the connections summary ("app and db share a
  // password", and so on). Same reason as clashNote and watchNote above:
  // no server-rendered element exists for this, and it is read-only, so it
  // gets its own modifier rather than borrowing --inuse's "this may be a
  // problem" amber — see staxx.css for why.
  var linkNote = document.createElement('p');
  linkNote.className = 'staxx-missing staxx-missing--link';
  linkNote.id = 'staxx-link-note';
  linkNote.hidden = true;
  if (gapNote && gapNote.parentNode) gapNote.parentNode.insertBefore(linkNote, gapNote);
  var errorBox    = document.getElementById('staxx-error');
  var missingNote = document.getElementById('staxx-missing');
  var scaffoldNote = document.getElementById('staxx-scaffold-note');
  // PLAN_84 phase 5 — "Not now" beside the offer bar's own "Review": only
  // ever shown alongside the quiet automatic lookup's own found-something
  // state, see showDetailOfferBar() further down.
  var scaffoldDismiss = document.getElementById('staxx-scaffold-dismiss');
  // PLAN_106 phase 4: latches true the first time this editor session's
  // reparse() finds a flagged dollar sign, so the modal is offered once per
  // open rather than reopening itself on every keystroke reparse() already
  // runs on — openEditor() is the only place that clears it back to false.
  var dollarModalOffered = false;
  var makePathsNote = document.getElementById('staxx-makepaths');
  var inUseNote     = document.getElementById('staxx-inusepaths');

  var tzModal     = document.getElementById('staxx-tz');
  var tzBands     = document.getElementById('staxx-tz-bands');
  var tzCaption   = document.getElementById('staxx-tz-caption');
  var tzChips     = document.getElementById('staxx-tz-chips');
  var tzSearch    = document.getElementById('staxx-tz-search');
  var tzList      = document.getElementById('staxx-tz-list');
  var tzMsg       = document.getElementById('staxx-tz-msg');

  var picker      = document.getElementById('staxx-picker');
  var pickerHere  = document.getElementById('staxx-picker-here');
  var pickerList  = document.getElementById('staxx-picker-list');
  var pickerMsg   = document.getElementById('staxx-picker-msg');
  var pickerNew   = document.getElementById('staxx-picker-newname');

  // The removal confirmation. May be null while the markup has not landed yet
  // on a stale page — guarded the same way suggestBox and findBar are above;
  // removeStack() falls back to window.confirm() when it is missing.
  var confirmModal  = document.getElementById('staxx-confirm');
  var confirmTitle  = document.getElementById('staxx-confirm-title');
  var confirmBody   = document.getElementById('staxx-confirm-body');
  var confirmMsg    = document.getElementById('staxx-confirm-msg');
  var confirmCancel = document.getElementById('staxx-confirm-cancel');
  var confirmGo     = document.getElementById('staxx-confirm-go');
  // The PHP-rendered label ("Cancel"), read once before any caller's own
  // wording overwrites it — PLAN_106's dollar-sign modal is the first caller
  // that wants something less generic ("Leave them") on the dismiss button,
  // and every other caller keeps reading as it always has by simply never
  // setting opts.cancelLabel.
  var confirmCancelDefault = confirmCancel ? confirmCancel.textContent : 'Cancel';
  // The optional third answer (PLAN_44 C2) — null-guarded the same way the
  // rest of this dialog already is, and hidden except when a caller passes
  // askConfirm() an extraLabel.
  var confirmExtra  = document.getElementById('staxx-confirm-extra');

  // PLAN_84 phase 3 — the "fill in this stack's details" chooser. Its own
  // dialog rather than a shape squeezed into #staxx-confirm above — see the
  // comment in StacksPage.php beside its markup for why.
  var detailModal   = document.getElementById('staxx-detail-modal');
  var detailBody    = document.getElementById('staxx-detail-body');
  var detailMsg     = document.getElementById('staxx-detail-msg');
  var detailCancel  = document.getElementById('staxx-detail-cancel');
  var detailGo      = document.getElementById('staxx-detail-go');
  var detailPlaceholders = document.getElementById('staxx-detail-placeholders');
  var detailBtn     = document.getElementById('staxx-detail-btn');

  // The Settings panel. May be null on a stale page — guarded the same way
  // confirmModal is above; openSettings() itself is a no-op without it.
  var settingsModal  = document.getElementById('staxx-settings');
  var settingsTabstrip = document.getElementById('staxx-settings-tabstrip');
  var settingsBody   = document.getElementById('staxx-settings-body');
  var settingsMsg    = document.getElementById('staxx-settings-msg');
  var settingsCancel = document.getElementById('staxx-settings-cancel');
  var settingsSave   = document.getElementById('staxx-settings-save');
  // StaXXCrypt's own state (PLAN_74 Part A piece 3) — script builds this
